properties.entry:
SET SQL_SAFE_UPDATES = 0;
START TRANSACTION;
SELECT @distance = 0;
SELECT @newOdometer = 0;
SELECT @newAttributes = '';

SELECT @fixedTime = 0;

set @lastStatus = 0;

SELECT @accountID := accountID, @deviceID := deviceID, @notes := notes,@odometer := lastOdometerKM, @previousTime := lastGPSTimestamp,@lastFuelLevel := lastFuelLevel,
@lastFuelLevel2 := lastFuelLevel2, @lastFuelTotal := lastFuelTotal  FROM Device WHERE imeiNumber = :device_id;
call gts.fix_time(:time,@fixedTime); call gts.check_imei_device(:device_id,@deviceID);
call gts.imei_check(:device_id,:attributes,@deviceID,1);
CALL gts.getDistance(:attributes, @distance);
call gts.getOdometer(@deviceID, @accountID,UNIX_TIMESTAMP(@fixedTime),@distance,@odometer,@newOdometer,:attributes, @newAttributes);
call gts.setLastValues(@lastFuelLevel, @lastFuelLevel2,@lastFuelTotal,@newAttributes, @notes);
UPDATE Device SET lastValidLatitude = :latitude, lastValidLongitude = :longitude, lastOdometerKM = @newOdometer, lastDistanceKM = @distance,
lastGPSTimestamp = UNIX_TIMESTAMP(@fixedTime), lastUpdateTime = UNIX_TIMESTAMP(NOW()), notes = @notes,lastFuelLevel = @lastFuelLevel,
lastFuelLevel2 = @lastFuelLevel2, lastFuelTotal = @lastFuelTotal   WHERE imeiNumber = :device_id;

call gts.updateLastStatusReturn(:device_id,:statusignition,@lastStatus);

INSERT INTO EventData (accountID, deviceID, timestamp, statusCode, latitude, longitude, speedKPH, heading, altitude, rawData, distanceKM, odometerKM, creationTime, address,gpsAge)
VALUES (@accountID, @deviceID, UNIX_TIMESTAMP(@fixedTime), 0, :latitude, :longitude, :speed,
:course, :altitude, @newAttributes, @distance, @newOdometer, UNIX_TIMESTAMP(NOW()), :address, @lastStatus);
COMMIT;
